import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"跟做：备份并在独立环境恢复文档、附件与任务","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/backup-restore","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/backup-restore.md","filePath":"tutorials/backup-restore.md"}'),d={name:"tutorials/backup-restore.md"};function i(r,e,c,n,p,l){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="跟做-备份并在独立环境恢复文档、附件与任务" tabindex="-1">跟做：备份并在独立环境恢复文档、附件与任务 <a class="header-anchor" href="#跟做-备份并在独立环境恢复文档、附件与任务" aria-label="Permalink to &quot;跟做：备份并在独立环境恢复文档、附件与任务&quot;">​</a></h1><p>本章回答“生产数据如何备份、如何证明能恢复”。备份不是“把卷目录拷走”，而是一个可审阅的过程：维护窗口内停止新的变更、等待在途请求排空，对数据库做一致性快照，同时按数据库登记核对每一个 ready 对象；恢复则永远进入一个独立的空环境，用归档加受保护配置重建，再用真实 API 旅程证明账号、文档、附件、排队任务都回来了。两条运维命令（<code>production-backup</code>、<code>production-restore</code>）覆盖日常操作，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">自动演练</a>把“备份→恢复→验证”整条链路做成一条命令，每次运行都从零生成密钥、随机项目名与数据。</p><h2 id="_1-备份里有什么、没有什么" tabindex="-1">1. 备份里有什么、没有什么 <a class="header-anchor" href="#_1-备份里有什么、没有什么" aria-label="Permalink to &quot;1. 备份里有什么、没有什么&quot;">​</a></h2><p><code>just production-backup</code> 产出的归档 = 数据库快照 + 对象清单 + 清单核对过的对象字节 + 报告：</p><table tabindex="0"><thead><tr><th>归档内容</th><th>形式</th></tr></thead><tbody><tr><td><code>database.dump</code></td><td><code>pg_dump -Fc</code> 自定义格式，含 <code>_sqlx_migrations</code>，可跨版本 <code>pg_restore</code></td></tr><tr><td><code>manifest.json</code></td><td>应用镜像与 digest、迁移版本与数量、每个 ready 文件的 <code>sha256</code> 与大小</td></tr><tr><td><code>objects/</code></td><td>清单里每个 ready 对象的原样字节，逐一按数据库摘要核对后落盘</td></tr><tr><td><code>backup-report.md</code></td><td>结论 PASS/FAIL 与检查明细，供人审阅</td></tr></tbody></table><p>清单只登记 ready 对象是设计使然：ready 对象不可变，且内容摘要就存在数据库里（<code>saas_core.files.sha256</code>），所以“数据库快照 + ready 对象”构成一个自洽的一致点——清单与快照互相印证，任何一边缺了都能被发现（多余对象只报告、不判失败，例如尚未清理的暂存键）。pending 上传的暂存对象不在备份里：恢复后它们按 TTL 过期并幂等清理，这正是演练要验证的行为。</p><p>密钥不在归档里。<code>POSTGRES_PASSWORD</code>、<code>S3_*</code>、<code>MAIL_ENCRYPTION_KEY</code> 属于受保护配置，恢复时从部署方的环境文件单独提供——丢掉归档不泄露密钥，丢掉环境文件只有归档也进不去数据库。归档与密钥分开保管、分开授权（本地 Caddy 根证书同样能签发入口证书，脚本只把它写进临时目录，绝不入档）。</p><h2 id="_2-维护窗口-停止变更、排空、快照" tabindex="-1">2. 维护窗口：停止变更、排空、快照 <a class="header-anchor" href="#_2-维护窗口-停止变更、排空、快照" aria-label="Permalink to &quot;2. 维护窗口：停止变更、排空、快照&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 归档落在 backups/&lt;时间戳&gt;/</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/production-backup.mjs" target="_blank" rel="noreferrer">备份脚本</a>执行完整的窗口序列并掐表：先停 API（停止新的 mutation，宽限期 30s，日志必须出现 <code>draining HTTP requests</code>），再停 Worker（在途认领收尾，宽限期 45s，日志必须出现 <code>stopping worker claims and draining current work</code>）；任何一个到达 compose 的强杀宽限期而不是自行退出，脚本立即失败。两个写入者都停了，<code>pg_dump</code> 拿到的才是无新变更的一致点——“不依赖停 API 就假设暂存 PUT 已停止”的反面要求就是必须真的 drain。窗口期间新请求无法进入，而已在队列里的任务（如导出）保留在数据库任务表中，恢复后由 Worker 认领完成，不丢失。备份结束时栈处于停止状态，照常 <code>just production-up</code> 重启即可。</p><p>对象侧不需要单独冻结：ready 对象不可变，清单按数据库逐行生成（<code>state = &#39;ready&#39;</code> 的 <code>ready_key</code>、<code>sha256</code>、<code>actual_size</code>），再经入口对桶做 ListObjectsV2 核对。对象操作用<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/lib/sigv4.mjs" target="_blank" rel="noreferrer">最小 SigV4 实现</a>以 <code>S3_PUBLIC_ENDPOINT</code> 签名——与预签名 URL 同一条路径，其正确性由 AWS 官方 get-vanilla 测试向量逐字节钉住（<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/tests/tooling/backup-sigv4.test.mjs" target="_blank" rel="noreferrer">测试</a>），并下载每个对象比对数据库摘要后才写入归档。</p><h2 id="_3-恢复-独立空环境-绝不覆盖" tabindex="-1">3. 恢复：独立空环境，绝不覆盖 <a class="header-anchor" href="#_3-恢复-独立空环境-绝不覆盖" aria-label="Permalink to &quot;3. 恢复：独立空环境，绝不覆盖&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ARCHIVE=backups/20260927-120000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/production-restore.mjs" target="_blank" rel="noreferrer">恢复脚本</a>的默认目标是独立环境：compose 项目名不同（默认 <code>axum-saas-production-restore-&lt;时间戳&gt;</code>），网络与卷全部新建。项目名与生产相同时脚本直接拒绝——同名意味着同卷，那是唯一的覆盖路径；发布端口与生产相同，所以生产组合必须先完全停止，要替换就得显式 <code>down -v</code> 旧环境，这个决定永远是人做的。脚本依次：起依赖 → <code>pg_restore --no-owner --exit-on-error</code>（半个数据库的“成功恢复”不会静默通过）→ <code>storage-init</code> 建桶 → 起入口（对象 PUT 要过 Caddy，签名才有效）→ 按 <code>manifest.json</code> 把 <code>objects/</code> 逐个签名 PUT 回桶 → 起应用 → 结构核对（就绪、迁移版本与清单一致、桶内容与清单一致），恢复报告落在归档里，恢复栈保持运行供人工检查。应用从不隐式迁移或建桶——恢复环境与首次部署遵守同一契约。</p><h2 id="_4-演练-自动证明这份归档真的能恢复" tabindex="-1">4. 演练：自动证明这份归档真的能恢复 <a class="header-anchor" href="#_4-演练-自动证明这份归档真的能恢复" aria-label="Permalink to &quot;4. 演练：自动证明这份归档真的能恢复&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">演练脚本</a>自建镜像、自生成密钥与环境文件（邮件已配置但失联、遥测端点不可达——降级贯穿全程），然后驱动第 2、3 节的同两条命令走完整链路并追加旅程断言：</p><ol><li><strong>种子</strong>：注册 owner、写入已知内容的文档、上传已知字节的附件并完成，再开一个<strong>永远不传字段的 pending 上传</strong>作为过期受害者，停 Worker 后排队一个导出。</li><li><strong>窗口与备份</strong>：<code>production-backup</code> 排空并掐表，产出 dump、清单、核对过的对象与备份报告。</li><li><strong>重建</strong>：演练 <code>down -v</code> 生产项目腾出端口，<code>production-restore</code> 用归档单独重建独立项目。</li><li><strong>旅程验证</strong>：原会话 Cookie 依然有效（会话在恢复的数据库里）；文档与附件逐字节读回；排队的导出被恢复后的 Worker 完成为 <code>succeeded</code>，zip 内容与原文一致；pending 上传过期到 <code>expired</code> 终态，<code>object_cleanup</code> 为暂存键登记了 <code>first_deleted_at</code>——尽管对象本来就不存在，清理保持幂等；没有任何任务以 <code>failed</code> 收场。</li><li><strong>报告</strong>：三份报告留在归档里（<code>drill-report.md</code>、<code>backup-report.md</code>、<code>restore-report.md</code>），PASS 之外任何一项失败都会让演练以 <code>[阶段名]</code> 前缀报错结束。</li></ol><p>上传 TTL 是 15 分钟（<code>upload_secs</code> 策略默认值），演练不会干等：它把恢复库里那一行的 <code>expires_at</code> 拨到过去，随后的过期、清理入队与幂等删除仍由真实的维护扫描（30 秒周期）与清理任务执行——拨快时钟的是演练，执行状态机的永远是生产代码。</p><p>演练是可重复的：项目名带 PID、密钥随机、结束 <code>down -v</code> 两个项目并删除环境文件与临时根证书；归档留在 <code>.scratch/</code> 下供审阅（其中只有演练数据）。若 80/443 被占，说明生产组合还在运行——先 <code>just production-down</code>，这也是“恢复不碰生产”约束的自然排错步骤。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/tests/tooling/backup-manifest.test.mjs" target="_blank" rel="noreferrer">清单逻辑测试</a>不需要 Docker 即可验证清单归一化、核对语义与报告渲染。</p><h2 id="_5-运行本章检查" tabindex="-1">5. 运行本章检查 <a class="header-anchor" href="#_5-运行本章检查" aria-label="Permalink to &quot;5. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-sigv4.test.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-manifest.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>本章与单机生产部署一样属于模板核心能力（Core），不在示例所有权清单中登记——备份恢复工具面向任何按模板部署的部署方，不随示例业务删除。备份与恢复是同一工具的两半：演练每次运行都同时证明“这份归档真的能恢复”，这是它比“备份成功”更强的承诺。</p><hr><p>源码版本：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/tutorials/22-backup-restore.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,25)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
